import 'package:stiv/features/diagnostic/models/hypothesis.dart';

// ─────────────────────────────────────────────────────────────────────────────
// HIPÓTESIS COMPARTIDAS — other_issue (aplica a cualquier dispositivo)
// ─────────────────────────────────────────────────────────────────────────────

const sharedOtherHypotheses = <Hypothesis>[
  Hypothesis(id: 'hardware_fault', label: 'Falla de hardware (componente físico)', description: 'Componente físico del equipo dañado por golpe, sobretensión eléctrica, humedad o desgaste natural. Puede ser un conector, placa secundaria o componente electrónico puntual.', recommendedActions: ['Paso 1 — Inspeccionar visualmente el equipo buscando señales de daño: quemaduras, condensadores abombados, conectores doblados, piezas sueltas o marcas de humedad.', 'Paso 2 — Verificar todos los cables de conexión interna (si el equipo permite abrirse de forma segura): cables de datos y alimentación al disco duro, ventilador y placa principal.', 'Paso 3 — Probar los módulos reemplazables por separado: cambiar el disco, la memoria (si aplica) o la fuente de poder por unidades conocidas como buenas.', 'Paso 4 — Documentar el número de serie, modelo y descripción exacta del problema antes de enviar a servicio técnico.', 'Paso 5 — Solicitar presupuesto de reparación por escrito al servicio técnico: si el costo supera el 60% del equipo nuevo, evaluar reemplazo.'], escalationThreshold: 0.50),
  Hypothesis(id: 'software_firmware_config', label: 'Error de firmware / configuración de sistema', description: 'La configuración del sistema, firmware desactualizado o parámetros incorrectos causan el mal funcionamiento. Es más común después de cortes de energía abruptos o actualizaciones fallidas.', recommendedActions: ['Paso 1 — Revisar los logs del sistema en el menú "Mantenimiento > Logs": buscar errores recurrentes o eventos en el momento del problema.', 'Paso 2 — Actualizar el firmware del equipo a la versión más reciente estable disponible en el sitio oficial del fabricante.', 'Paso 3 — Si el comportamiento es errático después de una actualización, verificar si el fabricante publicó un rollback o versión anterior.', 'Paso 4 — Realizar un restablecimiento de fábrica ("Default") y reconfigurar el equipo desde cero: exportar la configuración actual antes si el equipo lo permite.', 'Paso 5 — Implementar un UPS para proteger el equipo de cortes de energía abruptos que corrompen la configuración o el firmware.'], escalationThreshold: 0.45),
  Hypothesis(id: 'environmental_factor', label: 'Factor ambiental (temperatura / humedad / polvo)', description: 'Condiciones ambientales adversas afectan el rendimiento o vida útil del equipo: temperatura alta, humedad excesiva, polvo acumulado o vibración constante en el entorno de instalación.', recommendedActions: ['Paso 1 — Medir la temperatura del cuarto técnico con un termómetro: el rango ideal es 18–24°C. Temperaturas sobre 30°C reducen significativamente la vida útil de los componentes electrónicos.', 'Paso 2 — Medir la humedad relativa: debe estar entre 40–60% RH. Por encima del 80% hay riesgo de condensación y corrosión.', 'Paso 3 — Verificar que los gabinetes o racks tengan grado de protección adecuado para el entorno: IP65/IP66 para exteriores o ambientes con polvo.', 'Paso 4 — Realizar limpieza preventiva de polvo en todos los equipos del gabinete cada 3 meses en ambientes industriales o con mucho polvo.', 'Paso 5 — Instalar aire acondicionado de precisión en el cuarto técnico o bandejas de ventilación forzada en el rack para controlar la temperatura.'], escalationThreshold: 0.40),
  Hypothesis(id: 'access_credentials_error', label: 'Credenciales de acceso incorrectas o bloqueadas', description: 'No es posible acceder al equipo porque la contraseña fue cambiada, el usuario fue bloqueado por múltiples intentos fallidos, o las credenciales por defecto nunca fueron configuradas correctamente.', recommendedActions: ['Paso 1 — Verificar si el equipo tiene un período de bloqueo por intentos fallidos: esperar 5–30 minutos y volver a intentar con las credenciales correctas.', 'Paso 2 — Consultar el inventario de contraseñas del proyecto: muchas organizaciones documentan las credenciales de acceso en el momento de la instalación.', 'Paso 3 — Intentar con las credenciales por defecto del fabricante (documentadas en el manual): admin/admin, admin/12345, etc.', 'Paso 4 — Si la contraseña fue olvidada definitivamente, realizar el proceso de recuperación de contraseña del fabricante: algunos requieren fecha de exportación de configuración, otros un código GUID del dispositivo.', 'Paso 5 — Como último recurso, hacer reset de fábrica (botón físico): esto borrará toda la configuración y grabaciones del equipo.'], escalationThreshold: 0.35),
  Hypothesis(id: 'remote_access_failure', label: 'Falla de acceso remoto (P2P / puerto)', description: 'El sistema funciona localmente pero no es accesible de forma remota desde la app móvil o navegador externo. Problema de reenvío de puertos, IP dinámica o servicio P2P no activo.', recommendedActions: ['Paso 1 — Verificar primero que el sistema funcione correctamente en la red local (LAN): si no funciona localmente, el problema no es de acceso remoto.', 'Paso 2 — Comprobar si el servicio P2P/Cloud del NVR está habilitado y conectado: en el menú de red debe aparecer "Online" o con ícono verde.', 'Paso 3 — Si usa reenvío de puertos (Port Forwarding) en el router, verificar que los puertos del NVR (80, 8000, 554 típicamente) estén redirigidos correctamente a la IP interna del NVR.', 'Paso 4 — Si la IP pública es dinámica (cambia periódicamente), configurar un servicio DDNS (ej. DynDNS, No-IP, o el DDNS del propio fabricante) para mantener acceso estable.', 'Paso 5 — Verificar con el ISP si el servicio contratado tiene IP pública dedicada o si está detrás de CG-NAT (Carrier-Grade NAT): el CG-NAT impide el acceso remoto por port forwarding.'], escalationThreshold: 0.45),
];
